def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Near the finite end, defecting the last two rounds is weakly good:
    # it gains against unconditional cooperators and costs nothing against
    # strict retaliators when compared with mutual cooperation.
    if n >= 98:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    unprovoked = 0
    total_after_d = 0
    coop_after_d = 0

    episodes = 0
    max_d_streak = 0
    cur_d = 0
    in_d = False

    for i in range(n):
        m, o = history[i]

        if o == 'C':
            opp_c += 1
        else:
            cur_d += 1
            if not in_d:
                episodes += 1
                in_d = True
            if cur_d > max_d_streak:
                max_d_streak = cur_d

        if i > 0:
            prev_my = history[i - 1][0]

            # Opponent defected after we cooperated.
            if o == 'D' and prev_my == 'C':
                unprovoked += 1

            # Opponent's response to our previous defection.
            if prev_my == 'D':
                total_after_d += 1
                if o == 'C':
                    coop_after_d += 1

        if o == 'C':
            in_d = False
            cur_d = 0

    opp_d = n - opp_c
    opp_rate = (opp_c + 2.0) / (n + 4.0)

    if opp_c == 0:
        return 'D'

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    start8 = n - 8
    if start8 < 0:
        start8 = 0

    recent_d8 = 0
    for i in range(start8, n):
        if history[i][1] == 'D':
            recent_d8 += 1

    # Detect short repeated unprovoked bursts, e.g. periodic defectors.
    # Such opponents are better exploited than trusted.
    if (episodes >= 2 and unprovoked >= 2 and max_d_streak <= 3 and
            0.30 <= opp_rate <= 0.80):
        return 'D'

    # If the opponent has never defected, test for unconditional cooperation.
    # One probe is made around round 20. If they do not punish it, switch to
    # permanent defection because the match is finite and they are exploitable.
    if opp_d == 0:
        if n >= 20:
            confirmed = False
            start_check = n - 8
            if start_check < 0:
                start_check = 0

            # Look for a recent pattern: we defected, they cooperated,
            # then we cooperated and they cooperated again. This means they
            # did not punish our defection with the usual one-round lag.
            for i in range(start_check, n - 1):
                if (history[i][0] == 'D' and history[i][1] == 'C' and
                        history[i + 1][0] == 'C' and history[i + 1][1] == 'C'):
                    confirmed = True
                    break

            if confirmed:
                return 'D'

            # After probing, wait one round to observe whether retaliation comes.
            if my_last == 'D':
                return 'C'

            # Scheduled first probes. Once confirmed above, we defect forever.
            if n % 20 == 0:
                return 'D'

        return 'C'

    # If the opponent is mostly defecting now, defend.
    if opp_rate <= 0.28 and n > 8:
        return 'D'

    if recent_d8 >= 7 and n > 8:
        return 'D'

    # Opponent defected. Use a firm-but-forgiving rule that avoids
    # the parent's main failure mode: getting locked in mutual defection
    # after a short burst by a retaliating opponent.
    if opp_last == 'D':
        # If opponent's last defection was provoked by our previous D,
        # cooperate to reset unless they are already overwhelmingly D.
        if (n >= 2 and history[-2][0] == 'D' and
                recent_d8 <= 5 and opp_rate >= 0.35):
            return 'C'

        # Punish a single unprovoked/initial defection once.
        if streak_d == 1:
            return 'D'

        # After a short burst of defections, make up to two recovery attempts.
        # This recovers from strategies like four_D_TFT while limiting losses
        # against sustained defectors.
        if opp_rate >= 0.45 and streak_d <= 6:
            start = n - streak_d
            c_attempts = 0
            for i in range(start, n):
                if history[i][0] == 'C':
                    c_attempts += 1
            if c_attempts <= 2:
                return 'C'

        # If we are still in a mutual-defection spiral and recent history is
        # not overwhelmingly defection-heavy, make one more cautious reset.
        if (my_last == 'D' and recent_d8 <= 4 and opp_rate >= 0.30 and
                streak_d <= 10):
            cd_fail = 0
            start_fail = n - 6
            if start_fail < 0:
                start_fail = 0

            for i in range(start_fail, n):
                if history[i][0] == 'C' and history[i][1] == 'D':
                    cd_fail += 1

            if cd_fail <= 2:
                return 'C'

        return 'D'

    # Opponent cooperated last round.
    # After our own defection, return to cooperation to avoid punishment
    # unless they are a confirmed exploitable type handled above.
    if my_last == 'D':
        return 'C'

    # Very small random probes against high-quality cooperative opponents.
    # These are deliberately rare so they do not destabilize reciprocal play.
    if opp_rate >= 0.65 and recent_d8 == 0 and n >= 25:
        if rng.random() < 0.004:
            return 'D'

    if opp_rate >= 0.50 and recent_d8 <= 1:
        if rng.random() < 0.002:
            return 'D'

    return 'C'
